diff:
A result.json
A tmp/analyze.ps1
A tmp/crosscheck.ps1

--- result.json ---
{
  "ship_b": true,
  "sessions_a": 900,
  "sessions_b": 900,
  "completion_rate_a": 0.38,
  "completion_rate_b": 0.4667,
  "p_value": 0.000199
}


--- tmp/analyze.ps1 ---
$ErrorActionPreference = 'Stop'
$csv = Import-Csv '<WORKSPACE>\telemetry\playtest_ab.csv'

# Dedup by session_id (ETL resends sessions; keep first row per session)
$seen = @{}
$rows = foreach ($r in $csv) {
    $sid = $r.session_id.Trim()
    if (-not $seen.ContainsKey($sid)) { $seen[$sid] = $true; [pscustomobject]@{ id=$sid; variant=$r.variant; done=[int]$r.completed_tutorial } }
}

# Normalize variant: trim + lowercase
$stats = @{}
foreach ($r in $rows) {
    $v = $r.variant.Trim().ToLower()
    if (-not $stats.ContainsKey($v)) { $stats[$v] = @{ n=0; done=0 } }
    $stats[$v].n++
    $stats[$v].done += $r.done
}

Write-Host "total unique sessions: $($rows.Count)"
foreach ($k in ($stats.Keys | Sort-Object)) {
    Write-Host "variant '$k': n=$($stats[$k].n) done=$($stats[$k].done)"
}

$a = $stats['a']; $b = $stats['b']
$p_a = $a.done / $a.n
$p_b = $b.done / $b.n
Write-Host ("rate a = {0:N6} ({1}/{2})" -f $p_a, $a.done, $a.n)
Write-Host ("rate b = {0:N6} ({1}/{2})" -f $p_b, $b.done, $b.n)

# Two-proportion pooled z-test, two-sided
$p = ($a.done + $b.done) / ($a.n + $b.n)
$se = [Math]::Sqrt($p * (1 - $p) * (1/$a.n + 1/$b.n))
$z = ($p_b - $p_a) / $se

# Normal CDF via A&S 7.1.26
function Phi([double]$z) {
    if ($z -lt 0) { return 1 - (Phi(-$z)) }
    $t = 1 / (1 + 0.2316419 * $z)
    $d = [Math]::Exp(-$z * $z / 2) / [Math]::Sqrt(2 * [Math]::PI)
    $poly = $t * (0.319381530 + $t * (-0.356563782 + $t * (1.781477937 + $t * (-1.821255978 + $t * 1.330274429))))
    return 1 - $d * $poly
}
$pval = 2 * (1 - (Phi([Math]::Abs($z))))
Write-Host ("z = {0:N4}" -f $z)
Write-Host ("p_value = {0:N6}" -f $pval)
Write-Host ("significant at 0.05 (B > A): " + ($pval -lt 0.05 -and $p_b -gt $p_a))

# Cross-check: chi-square (equivalent to two-sided pooled z^2)
$chi2 = $z * $z
Write-Host ("chi2 = {0:N4}" -f $chi2)


--- tmp/crosscheck.ps1 ---
$c = Import-Csv '<WORKSPACE>\telemetry\playtest_ab.csv'
Write-Host ('rows=' + $c.Count)
$uniq = $c | Select-Object -ExpandProperty session_id | Sort-Object -Unique
Write-Host ('unique_ids=' + $uniq.Count)

# first-row-per-session dedup, counted differently: sort by session, keep first
$map = @{}
foreach ($r in $c) {
    $sid = $r.session_id
    if (-not $map.ContainsKey($sid)) { $map[$sid] = $r }
}
$a_n = 0; $a_d = 0; $b_n = 0; $b_d = 0
foreach ($sid in $map.Keys) {
    $r = $map[$sid]
    $v = $r.variant.Trim().ToLower()
    $done = [int]$r.completed_tutorial
    if ($v -eq 'a') { $a_n++; $a_d += $done }
    elseif ($v -eq 'b') { $b_n++; $b_d += $done }
    else { Write-Host ('UNEXPECTED variant: ' + $r.variant) }
}
Write-Host ("a: n=$a_n done=$a_d rate=" + [Math]::Round($a_d / $a_n, 6))
Write-Host ("b: n=$b_n done=$b_d rate=" + [Math]::Round($b_d / $b_n, 6))

# p-value via chi-square on the 2x2 table, using Wilson-Hilferty-free approach:
# chi2 = N*(ad-bc)^2 / ((a+b)(c+d)(a+c)(b+d)), then p = 2*(1-Phi(sqrt(chi2)))
$a = $a_d; $b2 = $a_n - $a_d; $c2 = $b_d; $d = $b_n - $b_d
$N = $a_n + $b_n
$chi2 = $N * (($a * $d - $b2 * $c2) * ($a * $d - $b2 * $c2)) / (($a + $b2) * ($c2 + $d) * ($a + $c2) * ($b2 + $d))
function Phi([double]$z) {
    if ($z -lt 0) { return 1 - (Phi(-$z)) }
    $t = 1 / (1 + 0.2316419 * $z)
    $dd = [Math]::Exp(-$z * $z / 2) / [Math]::Sqrt(2 * [Math]::PI)
    return 1 - $dd * $t * (0.319381530 + $t * (-0.356563782 + $t * (1.781477937 + $t * (-1.821255978 + $t * 1.330274429))))
}
Write-Host ('chi2=' + [Math]::Round($chi2, 4) + ' p=' + [Math]::Round(2 * (1 - (Phi([Math]::Sqrt($chi2)))), 6))
